40	/**
41	 * Linear mapping a value from domain to range
42	 * @param  val
43	 * @param  domain Domain extent domain[0] can be bigger than domain[1]
44	 * @param  range  Range extent range[0] can be bigger than range[1]
45	 * @param  clamp Default to be false
46	 */
47	export function linearMap(
48	    val: number,
49	    domain: number[],
50	    range: number[],
51	    clamp?: boolean
52	): number {
53	    const d0 = domain[0];
54	    const d1 = domain[1];
55	    const r0 = range[0];
56	    const r1 = range[1];
57	
58	    const subDomain = d1 - d0;
59	    const subRange = r1 - r0;
60	
61	    if (subDomain === 0) {
62	        return subRange === 0
63	            ? r0
64	            : (r0 + r1) / 2;
65	    }
66	
67	    // Avoid accuracy problem in edge, such as
68	    // 146.39 - 62.83 === 83.55999999999999.
69	    // See echarts/test/ut/spec/util/number.js#linearMap#accuracyError
70	    // It is a little verbose for efficiency considering this method
71	    // is a hotspot.
72	    if (clamp) {
73	        if (subDomain > 0) {
74	            if (val <= d0) {
75	                return r0;
76	            }
77	            else if (val >= d1) {
78	                return r1;
79	            }
80	        }
81	        else {
82	            if (val >= d0) {
83	                return r0;
84	            }
85	            else if (val <= d1) {
86	                return r1;
87	            }
88	        }
89	    }
90	    else {
91	        if (val === d0) {
92	            return r0;
93	        }
94	        if (val === d1) {
95	            return r1;
96	        }
97	    }
98	
99	    return (val - d0) / subDomain * subRange + r0;
100	}
