102	/**
103	 * Convert a percent string to absolute number.
104	 * Returns NaN if percent is not a valid string or number
105	 */
106	export function parsePercent(percent: number | string, all: number): number {
107	    switch (percent) {
108	        case 'center':
109	        case 'middle':
110	            percent = '50%';
111	            break;
112	        case 'left':
113	        case 'top':
114	            percent = '0%';
115	            break;
116	        case 'right':
117	        case 'bottom':
118	            percent = '100%';
119	            break;
120	    }
121	    if (zrUtil.isString(percent)) {
122	        if (_trim(percent).match(/%$/)) {
123	            return parseFloat(percent) / 100 * all;
124	        }
125	
126	        return parseFloat(percent);
127	    }
128	
129	    return percent == null ? NaN : +percent;
130	}
