132	/**
133	 * (1) Fix rounding error of float numbers.
134	 * (2) Support return string to avoid scientific notation like '3.5e-7'.
135	 */
136	export function round(x: number | string, precision?: number): number;
137	export function round(x: number | string, precision: number, returnStr: false): number;
138	export function round(x: number | string, precision: number, returnStr: true): string;
139	export function round(x: number | string, precision?: number, returnStr?: boolean): string | number {
140	    if (precision == null) {
141	        precision = 10;
142	    }
143	    // Avoid range error
144	    precision = Math.min(Math.max(0, precision), ROUND_SUPPORTED_PRECISION_MAX);
145	    // PENDING: 1.005.toFixed(2) is '1.00' rather than '1.01'
146	    x = (+x).toFixed(precision);
147	    return (returnStr ? x : +x);
148	}
