150	/**
151	 * Inplacd asc sort arr.
152	 * The input arr will be modified.
153	 */
154	export function asc<T extends number[]>(arr: T): T {
155	    arr.sort(function (a, b) {
156	        return a - b;
157	    });
158	    return arr;
159	}
