161	/**
162	 * Get precision.
163	 */
164	export function getPrecision(val: string | number): number {
165	    val = +val;
166	    if (isNaN(val)) {
167	        return 0;
168	    }
169	
170	    // It is much faster than methods converting number to string as follows
171	    //      let tmp = val.toString();
172	    //      return tmp.length - 1 - tmp.indexOf('.');
173	    // especially when precision is low
174	    // Notice:
175	    // (1) If the loop count is over about 20, it is slower than `getPrecisionSafe`.
176	    //     (see https://jsbench.me/2vkpcekkvw/1)
177	    // (2) If the val is less than for example 1e-15, the result may be incorrect.
178	    //     (see test/ut/spec/util/number.test.ts `getPrecision_equal_random`)
179	    if (val > 1e-14) {
180	        let e = 1;
181	        for (let i = 0; i < 15; i++, e *= 10) {
182	            if (Math.round(val * e) / e === val) {
183	                return i;
184	            }
185	        }
186	    }
187	
188	    return getPrecisionSafe(val);
189	}
190	
191	/**
192	 * Get precision with slow but safe method
193	 */
194	export function getPrecisionSafe(val: string | number): number {
195	    // toLowerCase for: '3.4E-12'
196	    const str = val.toString().toLowerCase();
197	
198	    // Consider scientific notation: '3.4e-12' '3.4e+12'
199	    const eIndex = str.indexOf('e');
200	    const exp = eIndex > 0 ? +str.slice(eIndex + 1) : 0;
201	    const significandPartLen = eIndex > 0 ? eIndex : str.length;
202	    const dotIndex = str.indexOf('.');
203	    const decimalPartLen = dotIndex < 0 ? 0 : significandPartLen - 1 - dotIndex;
204	    return Math.max(0, decimalPartLen - exp);
205	}
