207	/**
208	 * Minimal dicernible data precisioin according to a single pixel.
209	 */
210	export function getPixelPrecision(dataExtent: [number, number], pixelExtent: [number, number]): number {
211	    const log = Math.log;
212	    const LN10 = Math.LN10;
213	    const dataQuantity = Math.floor(log(dataExtent[1] - dataExtent[0]) / LN10);
214	    const sizeQuantity = Math.round(log(Math.abs(pixelExtent[1] - pixelExtent[0])) / LN10);
215	    // toFixed() digits argument must be between 0 and 20.
216	    const precision = Math.min(Math.max(-dataQuantity + sizeQuantity, 0), 20);
217	    return !isFinite(precision) ? 20 : precision;
218	}
