220	/**
221	 * Get a data of given precision, assuring the sum of percentages
222	 * in valueList is 1.
223	 * The largest remainder method is used.
224	 * https://en.wikipedia.org/wiki/Largest_remainder_method
225	 *
226	 * @param valueList a list of all data
227	 * @param idx index of the data to be processed in valueList
228	 * @param precision integer number showing digits of precision
229	 * @return percent ranging from 0 to 100
230	 */
231	export function getPercentWithPrecision(valueList: number[], idx: number, precision: number): number {
232	    if (!valueList[idx]) {
233	        return 0;
234	    }
235	
236	    const seats = getPercentSeats(valueList, precision);
237	
238	    return seats[idx] || 0;
239	}
