241	/**
242	 * Get a data of given precision, assuring the sum of percentages
243	 * in valueList is 1.
244	 * The largest remainder method is used.
245	 * https://en.wikipedia.org/wiki/Largest_remainder_method
246	 *
247	 * @param valueList a list of all data
248	 * @param precision integer number showing digits of precision
249	 * @return {Array<number>}
250	 */
251	export function getPercentSeats(valueList: number[], precision: number): number[] {
252	    const sum = zrUtil.reduce(valueList, function (acc, val) {
253	        return acc + (isNaN(val) ? 0 : val);
254	    }, 0);
255	    if (sum === 0) {
256	        return [];
257	    }
258	
259	    const digits = Math.pow(10, precision);
260	    const votesPerQuota = zrUtil.map(valueList, function (val) {
261	        return (isNaN(val) ? 0 : val) / sum * digits * 100;
262	    });
263	    const targetSeats = digits * 100;
264	
265	    const seats = zrUtil.map(votesPerQuota, function (votes) {
266	        // Assign automatic seats.
267	        return Math.floor(votes);
268	    });
269	    let currentSum = zrUtil.reduce(seats, function (acc, val) {
270	        return acc + val;
271	    }, 0);
272	
273	    const remainder = zrUtil.map(votesPerQuota, function (votes, idx) {
274	        return votes - seats[idx];
275	    });
276	
277	    // Has remainding votes.
278	    while (currentSum < targetSeats) {
279	        // Find next largest remainder.
280	        let max = Number.NEGATIVE_INFINITY;
281	        let maxId = null;
282	        for (let i = 0, len = remainder.length; i < len; ++i) {
283	            if (remainder[i] > max) {
284	                max = remainder[i];
285	                maxId = i;
286	            }
287	        }
288	
289	        // Add a vote to max remainder.
290	        ++seats[maxId];
291	        remainder[maxId] = 0;
292	        ++currentSum;
293	    }
294	    return zrUtil.map(seats, function (seat) {
295	        return seat / digits;
296	    });
297	}
