299	/**
300	 * Solve the floating point adding problem like 0.1 + 0.2 === 0.30000000000000004
301	 * See <http://0.30000000000000004.com/>
302	 */
303	export function addSafe(val0: number, val1: number): number {
304	    const maxPrecision = Math.max(getPrecision(val0), getPrecision(val1));
305	    // const multiplier = Math.pow(10, maxPrecision);
306	    // return (Math.round(val0 * multiplier) + Math.round(val1 * multiplier)) / multiplier;
307	    const sum = val0 + val1;
308	    // // PENDING: support more?
309	    return maxPrecision > ROUND_SUPPORTED_PRECISION_MAX
310	        ? sum : round(sum, maxPrecision);
311	}
