332	// eslint-disable-next-line
333	const TIME_REG = /^(?:(\d{4})(?:[-\/](\d{1,2})(?:[-\/](\d{1,2})(?:[T ](\d{1,2})(?::(\d{1,2})(?::(\d{1,2})(?:[.,](\d+))?)?)?(Z|[\+\-]\d\d:?\d\d)?)?)?)?)?$/; // jshint ignore:line
334	
335	/**
336	 * @param value valid type: number | string | Date, otherwise return `new Date(NaN)`
337	 *   These values can be accepted:
338	 *   + An instance of Date, represent a time in its own time zone.
339	 *   + Or string in a subset of ISO 8601, only including:
340	 *     + only year, month, date: '2012-03', '2012-03-01', '2012-03-01 05', '2012-03-01 05:06',
341	 *     + separated with T or space: '2012-03-01T12:22:33.123', '2012-03-01 12:22:33.123',
342	 *     + time zone: '2012-03-01T12:22:33Z', '2012-03-01T12:22:33+8000', '2012-03-01T12:22:33-05:00',
343	 *     all of which will be treated as local time if time zone is not specified
344	 *     (see <https://momentjs.com/>).
345	 *   + Or other string format, including (all of which will be treated as local time):
346	 *     '2012', '2012-3-1', '2012/3/1', '2012/03/01',
347	 *     '2009/6/12 2:00', '2009/6/12 2:05:08', '2009/6/12 2:05:08.123'
348	 *   + a timestamp, which represent a time in UTC.
349	 * @return date Never be null/undefined. If invalid, return `new Date(NaN)`.
350	 */
351	export function parseDate(value: unknown): Date {
352	    if (value instanceof Date) {
353	        return value;
354	    }
355	    else if (zrUtil.isString(value)) {
356	        // Different browsers parse date in different way, so we parse it manually.
357	        // Some other issues:
358	        // new Date('1970-01-01') is UTC,
359	        // new Date('1970/01/01') and new Date('1970-1-01') is local.
360	        // See issue #3623
361	        const match = TIME_REG.exec(value);
362	
363	        if (!match) {
364	            // return Invalid Date.
365	            return new Date(NaN);
366	        }
367	
368	        // Use local time when no timezone offset is specified.
369	        if (!match[8]) {
370	            // match[n] can only be string or undefined.
371	            // But take care of '12' + 1 => '121'.
372	            return new Date(
373	                +match[1],
374	                +(match[2] || 1) - 1,
375	                +match[3] || 1,
376	                +match[4] || 0,
377	                +(match[5] || 0),
378	                +match[6] || 0,
379	                match[7] ? +match[7].substring(0, 3) : 0
380	            );
381	        }
382	        // Timezoneoffset of Javascript Date has considered DST (Daylight Saving Time,
383	        // https://tc39.github.io/ecma262/#sec-daylight-saving-time-adjustment).
384	        // For example, system timezone is set as "Time Zone: America/Toronto",
385	        // then these code will get different result:
386	        // `new Date(1478411999999).getTimezoneOffset();  // get 240`
387	        // `new Date(1478412000000).getTimezoneOffset();  // get 300`
388	        // So we should not use `new Date`, but use `Date.UTC`.
389	        else {
390	            let hour = +match[4] || 0;
391	            if (match[8].toUpperCase() !== 'Z') {
392	                hour -= +match[8].slice(0, 3);
393	            }
394	            return new Date(Date.UTC(
395	                +match[1],
396	                +(match[2] || 1) - 1,
397	                +match[3] || 1,
398	                hour,
399	                +(match[5] || 0),
400	                +match[6] || 0,
401	                match[7] ? +match[7].substring(0, 3) : 0
402	            ));
403	        }
404	    }
405	    else if (value == null) {
406	        return new Date(NaN);
407	    }
408	
409	    return new Date(Math.round(value as number));
410	}
