412	/**
413	 * Quantity of a number. e.g. 0.1, 1, 10, 100
414	 *
415	 * @param val
416	 * @return
417	 */
418	export function quantity(val: number): number {
419	    return Math.pow(10, quantityExponent(val));
420	}
421	
422	/**
423	 * Exponent of the quantity of a number
424	 * e.g., 1234 equals to 1.234*10^3, so quantityExponent(1234) is 3
425	 *
426	 * @param val non-negative value
427	 * @return
428	 */
429	export function quantityExponent(val: number): number {
430	    if (val === 0) {
431	        return 0;
432	    }
433	
434	    let exp = Math.floor(Math.log(val) / Math.LN10);
435	    /**
436	     * exp is expected to be the rounded-down result of the base-10 log of val.
437	     * But due to the precision loss with Math.log(val), we need to restore it
438	     * using 10^exp to make sure we can get val back from exp. #11249
439	     */
440	    if (val / Math.pow(10, exp) >= 10) {
441	        exp++;
442	    }
443	    return exp;
444	}
