446	/**
447	 * find a “nice” number approximately equal to x. Round the number if round = true,
448	 * take ceiling if round = false. The primary observation is that the “nicest”
449	 * numbers in decimal are 1, 2, and 5, and all power-of-ten multiples of these numbers.
450	 *
451	 * See "Nice Numbers for Graph Labels" of Graphic Gems.
452	 *
453	 * @param  val Non-negative value.
454	 * @param  round
455	 * @return Niced number
456	 */
457	export function nice(val: number, round?: boolean): number {
458	    const exponent = quantityExponent(val);
459	    const exp10 = Math.pow(10, exponent);
460	    const f = val / exp10; // 1 <= f < 10
461	    let nf;
462	    if (round) {
463	        if (f < 1.5) {
464	            nf = 1;
465	        }
466	        else if (f < 2.5) {
467	            nf = 2;
468	        }
469	        else if (f < 4) {
470	            nf = 3;
471	        }
472	        else if (f < 7) {
473	            nf = 5;
474	        }
475	        else {
476	            nf = 10;
477	        }
478	    }
479	    else {
480	        if (f < 1) {
481	            nf = 1;
482	        }
483	        else if (f < 2) {
484	            nf = 2;
485	        }
486	        else if (f < 3) {
487	            nf = 3;
488	        }
489	        else if (f < 5) {
490	            nf = 5;
491	        }
492	        else {
493	            nf = 10;
494	        }
495	    }
496	    val = nf * exp10;
497	
498	    // Fix 3 * 0.1 === 0.30000000000000004 issue (see IEEE 754).
499	    // 20 is the uppper bound of toFixed.
500	    return exponent >= -20 ? +val.toFixed(exponent < 0 ? -exponent : 0) : val;
501	}
