503	/**
504	 * This code was copied from "d3.js"
505	 * <https://github.com/d3/d3/blob/9cc9a875e636a1dcf36cc1e07bdf77e1ad6e2c74/src/arrays/quantile.js>.
506	 * See the license statement at the head of this file.
507	 * @param ascArr
508	 */
509	export function quantile(ascArr: number[], p: number): number {
510	    const H = (ascArr.length - 1) * p + 1;
511	    const h = Math.floor(H);
512	    const v = +ascArr[h - 1];
513	    const e = H - h;
514	    return e ? v + e * (ascArr[h] - v) : v;
515	}
