517	type IntervalItem = {
518	    interval: [number, number]
519	    close: [0 | 1, 0 | 1]
520	};
521	/**
522	 * Order intervals asc, and split them when overlap.
523	 * expect(numberUtil.reformIntervals([
524	 *     {interval: [18, 62], close: [1, 1]},
525	 *     {interval: [-Infinity, -70], close: [0, 0]},
526	 *     {interval: [-70, -26], close: [1, 1]},
527	 *     {interval: [-26, 18], close: [1, 1]},
528	 *     {interval: [62, 150], close: [1, 1]},
529	 *     {interval: [106, 150], close: [1, 1]},
530	 *     {interval: [150, Infinity], close: [0, 0]}
531	 * ])).toEqual([
532	 *     {interval: [-Infinity, -70], close: [0, 0]},
533	 *     {interval: [-70, -26], close: [1, 1]},
534	 *     {interval: [-26, 18], close: [0, 1]},
535	 *     {interval: [18, 62], close: [0, 1]},
536	 *     {interval: [62, 150], close: [0, 1]},
537	 *     {interval: [150, Infinity], close: [0, 0]}
538	 * ]);
539	 * @param list, where `close` mean open or close
540	 *        of the interval, and Infinity can be used.
541	 * @return The origin list, which has been reformed.
542	 */
543	export function reformIntervals(list: IntervalItem[]): IntervalItem[] {
544	    list.sort(function (a, b) {
545	        return littleThan(a, b, 0) ? -1 : 1;
546	    });
547	
548	    let curr = -Infinity;
549	    let currClose = 1;
550	    for (let i = 0; i < list.length;) {
551	        const interval = list[i].interval;
552	        const close = list[i].close;
553	
554	        for (let lg = 0; lg < 2; lg++) {
555	            if (interval[lg] <= curr) {
556	                interval[lg] = curr;
557	                close[lg] = (!lg ? 1 - currClose : 1) as 0 | 1;
558	            }
559	            curr = interval[lg];
560	            currClose = close[lg];
561	        }
562	
563	        if (interval[0] === interval[1] && close[0] * close[1] !== 1) {
564	            list.splice(i, 1);
565	        }
566	        else {
567	            i++;
568	        }
569	    }
570	
571	    return list;
572	
573	    function littleThan(a: IntervalItem, b: IntervalItem, lg: number): boolean {
574	        return a.interval[lg] < b.interval[lg]
575	            || (
576	                a.interval[lg] === b.interval[lg]
577	                && (
578	                    (a.close[lg] - b.close[lg] === (!lg ? 1 : -1))
579	                    || (!lg && littleThan(a, b, 1))
580	                )
581	            );
582	    }
583	}
