585	/**
586	 * [Numeric is defined as]:
587	 *     `parseFloat(val) == val`
588	 * For example:
589	 * numeric:
590	 *     typeof number except NaN, '-123', '123', '2e3', '-2e3', '011', 'Infinity', Infinity,
591	 *     and they rounded by white-spaces or line-terminal like ' -123 \n ' (see es spec)
592	 * not-numeric:
593	 *     null, undefined, [], {}, true, false, 'NaN', NaN, '123ab',
594	 *     empty string, string with only white-spaces or line-terminal (see es spec),
595	 *     0x12, '0x12', '-0x12', 012, '012', '-012',
596	 *     non-string, ...
597	 *
598	 * @test See full test cases in `test/ut/spec/util/number.js`.
599	 * @return Must be a typeof number. If not numeric, return NaN.
600	 */
601	export function numericToNumber(val: unknown): number {
602	    const valFloat = parseFloat(val as string);
603	    return (
604	        valFloat == val // eslint-disable-line eqeqeq
605	        && (valFloat !== 0 || !zrUtil.isString(val) || val.indexOf('x') <= 0) // For case ' 0x0 '.
606	    ) ? valFloat : NaN;
607	}
608	
609	/**
610	 * Definition of "numeric": see `numericToNumber`.
611	 */
612	export function isNumeric(val: unknown): val is number {
613	    return !isNaN(numericToNumber(val));
614	}
