625	/**
626	 * Get the greatest common divisor.
627	 *
628	 * @param {number} a one number
629	 * @param {number} b the other number
630	 */
631	export function getGreatestCommonDividor(a: number, b: number): number {
632	    if (b === 0) {
633	        return a;
634	    }
635	    return getGreatestCommonDividor(b, a % b);
636	}
637	
638	/**
639	 * Get the least common multiple.
640	 *
641	 * @param {number} a one number
642	 * @param {number} b the other number
643	 */
644	export function getLeastCommonMultiple(a: number, b: number) {
645	    if (a == null) {
646	        return b;
647	    }
648	    if (b == null) {
649	        return a;
650	    }
651	    return a * b / getGreatestCommonDividor(a, b);
652	}
