114	class FilterOrderComparator implements FilterComparator {
115	    private _rvalFloat: number;
116	    private _opFn: (lval: unknown, rval: unknown) => boolean;
117	    constructor(op: OrderRelationOperator, rval: unknown) {
118	        if (!isNumber(rval)) {
119	            let errMsg = '';
120	            if (__DEV__) {
121	                errMsg = 'rvalue of "<", ">", "<=", ">=" can only be number in filter.';
122	            }
123	            throwError(errMsg);
124	        }
125	        this._opFn = ORDER_COMPARISON_OP_MAP[op];
126	        this._rvalFloat = numericToNumber(rval);
127	    }
128	    // Performance sensitive.
129	    evaluate(lval: unknown): boolean {
130	        // Most cases is 'number', and typeof maybe 10 times faseter than parseFloat.
131	        return isNumber(lval)
132	            ? this._opFn(lval, this._rvalFloat)
133	            : this._opFn(numericToNumber(lval), this._rvalFloat);
134	    }
