137	export class SortOrderComparator {
138	    private _incomparable: number;
139	    private _resultLT: -1 | 1;
140	    /**
141	     * @param order by default: 'asc'
142	     * @param incomparable by default: Always on the tail.
143	     *        That is, if 'asc' => 'max', if 'desc' => 'min'
144	     *        See the definition of "incomparable" in [SORT_COMPARISON_RULE].
145	     */
146	    constructor(order: 'asc' | 'desc', incomparable: 'min' | 'max') {
147	        const isDesc = order === 'desc';
148	        this._resultLT = isDesc ? 1 : -1;
149	        if (incomparable == null) {
150	            incomparable = isDesc ? 'min' : 'max';
151	        }
152	        this._incomparable = incomparable === 'min' ? -Infinity : Infinity;
153	    }
154	    // See [SORT_COMPARISON_RULE].
155	    // Performance sensitive.
156	    evaluate(lval: unknown, rval: unknown): -1 | 0 | 1 {
157	        // Most cases is 'number', and typeof maybe 10 times faseter than parseFloat.
158	        let lvalFloat = isNumber(lval) ? lval : numericToNumber(lval);
159	        let rvalFloat = isNumber(rval) ? rval : numericToNumber(rval);
160	        const lvalNotNumeric = isNaN(lvalFloat as number);
161	        const rvalNotNumeric = isNaN(rvalFloat as number);
162	
163	        if (lvalNotNumeric) {
164	            lvalFloat = this._incomparable;
165	        }
166	        if (rvalNotNumeric) {
167	            rvalFloat = this._incomparable;
168	        }
169	        if (lvalNotNumeric && rvalNotNumeric) {
170	            const lvalIsStr = isString(lval);
171	            const rvalIsStr = isString(rval);
172	            if (lvalIsStr) {
173	                lvalFloat = rvalIsStr ? lval as unknown as number : 0;
174	            }
175	            if (rvalIsStr) {
176	                rvalFloat = lvalIsStr ? rval as unknown as number : 0;
177	            }
178	        }
179	
180	        return lvalFloat < rvalFloat ? this._resultLT
181	            : lvalFloat > rvalFloat ? (-this._resultLT as -1 | 1)
182	            : 0;
183	    }
184	}
