186	class FilterEqualityComparator implements FilterComparator {
187	    private _isEQ: boolean;
188	    private _rval: unknown;
189	    private _rvalTypeof: string;
190	    private _rvalFloat: number;
191	    constructor(isEq: boolean, rval: unknown) {
192	        this._rval = rval;
193	        this._isEQ = isEq;
194	        this._rvalTypeof = typeof rval;
195	        this._rvalFloat = numericToNumber(rval);
196	    }
197	    // Performance sensitive.
198	    evaluate(lval: unknown): boolean {
199	        let eqResult = lval === this._rval;
200	        if (!eqResult) {
201	            const lvalTypeof = typeof lval;
202	            if (lvalTypeof !== this._rvalTypeof && (lvalTypeof === 'number' || this._rvalTypeof === 'number')) {
203	                eqResult = numericToNumber(lval) === this._rvalFloat;
204	            }
205	        }
206	        return this._isEQ ? eqResult : !eqResult;
207	    }
208	}
