210	type OrderRelationOperator = 'lt' | 'lte' | 'gt' | 'gte';
211	export type RelationalOperator = OrderRelationOperator | 'eq' | 'ne';
212	
213	/**
214	 * [FILTER_COMPARISON_RULE]
215	 * `lt`|`lte`|`gt`|`gte`:
216	 * + rval must be a number. And lval will be converted to number (`numericToNumber`) to compare.
217	 * `eq`:
218	 * + If same type, compare with `===`.
219	 * + If there is one number, convert to number (`numericToNumber`) to compare.
220	 * + Else return `false`.
221	 * `ne`:
222	 * + Not `eq`.
223	 *
224	 *
225	 * [SORT_COMPARISON_RULE]
226	 * All the values are grouped into three categories:
227	 * + "numeric" (number and numeric string)
228	 * + "non-numeric-string" (string that excluding numeric string)
229	 * + "others"
230	 * "numeric" vs "numeric": values are ordered by number order.
231	 * "non-numeric-string" vs "non-numeric-string": values are ordered by ES spec (#sec-abstract-relational-comparison).
232	 * "others" vs "others": do not change order (always return 0).
233	 * "numeric" vs "non-numeric-string": "non-numeric-string" is treated as "incomparable".
234	 * "number" vs "others": "others" is treated as "incomparable".
235	 * "non-numeric-string" vs "others": "others" is treated as "incomparable".
236	 * "incomparable" will be seen as -Infinity or Infinity (depends on the settings).
237	 * MEMO:
238	 *   Non-numeric string sort makes sense when we need to put the items with the same tag together.
239	 *   But if we support string sort, we still need to avoid the misleading like `'2' > '12'`,
240	 *   So we treat "numeric-string" sorted by number order rather than string comparison.
241	 *
242	 *
243	 * [CHECK_LIST_OF_THE_RULE_DESIGN]
244	 * + Do not support string comparison until required. And also need to
245	 *   avoid the misleading of "2" > "12".
246	 * + Should avoid the misleading case:
247	 *   `" 22 " gte "22"` is `true` but `" 22 " eq "22"` is `false`.
248	 * + JS bad case should be avoided: null <= 0, [] <= 0, ' ' <= 0, ...
249	 * + Only "numeric" can be converted to comparable number, otherwise converted to NaN.
250	 *   See `util/number.ts#numericToNumber`.
251	 *
252	 * @return If `op` is not `RelationalOperator`, return null;
253	 */
254	export function createFilterComparator(
255	    op: string,
256	    rval?: unknown
257	): FilterComparator {
258	    return (op === 'eq' || op === 'ne')
259	        ? new FilterEqualityComparator(op === 'eq', rval)
260	        : hasOwn(ORDER_COMPARISON_OP_MAP, op)
261	        ? new FilterOrderComparator(op as OrderRelationOperator, rval)
262	        : null;
263	}
