import { guessOrdinal } from '@/src/data/helper/sourceHelper';
import { createSourceFromSeriesDataOption } from '@/src/data/Source';

describe('data/bigint', function () {

    it('numericToNumber_bigint_not_throw', function () {
        expect(() => numericToNumber(BigInt(123))).not.toThrow();
        expect(numericToNumber(BigInt(123))).toEqual(123);
        expect(numericToNumber(BigInt(0))).toEqual(0);
        expect(isNumeric(BigInt(5))).toEqual(true);
        // Other paths keep working as before.
        expect(numericToNumber('  123  ')).toEqual(123);
        expect(isNaN(numericToNumber('abc'))).toEqual(true);
    });

    it('parseDate_bigint_not_throw', function () {
        const ts = +new Date(2012, 5, 12);
        expect(() => parseDate(BigInt(ts))).not.toThrow();
        expect(+parseDate(BigInt(ts))).toEqual(ts);
    });

    it('parseDataValue_bigint_not_throw', function () {
        expect(() => parseDataValue(BigInt(11), { type: 'float' })).not.toThrow();
        expect(parseDataValue(BigInt(11), { type: 'float' })).toEqual(11);
        expect(() => parseDataValue(BigInt(11), { type: 'time' })).not.toThrow();
        expect(parseDataValue(BigInt(11), { type: 'time' })).toEqual(11);
    });

    it('guessOrdinal_bigint_not_throw', function () {
        const source = createSourceFromSeriesDataOption([
            BigInt(11), BigInt(22), BigInt(33)
        ] as unknown as number[]);
        expect(() => guessOrdinal(source, 0)).not.toThrow();
    });

    it('initData_bigint_not_throw', function () {
        expect(() => {
            const data = new SeriesData(['x', 'y'], new Model());
            data.initData([
                [BigInt(10), BigInt(15)],
                [BigInt(20), BigInt(25)]
            ] as unknown as number[][]);
            expect(data.get('x', 0)).toEqual(10);
            expect(data.get('y', 1)).toEqual(25);
        }).not.toThrow();
    });

    it('setOption_with_bigint_data_not_throw', function () {
        const chart = createChart();
        expect(() => {
            chart.setOption({
                xAxis: {
                    type: 'category',
                    data: ['A', 'B', 'C']
                },
                yAxis: {},
                series: [{
                    type: 'bar',
                    data: [BigInt(11), BigInt(22), BigInt(33)] as unknown as number[]
                }]
            });
        }).not.toThrow();
        removeChart(chart);
    });

});

