import { createChart, removeChart } from '../../core/utHelper';
import { EChartsType } from '@/src/echarts';
import SeriesModel from '@/src/model/Series';

describe('data/helper/linkSeriesData', function () {

    let chart: EChartsType;

    beforeEach(function () {
        chart = createChart();
    });

    afterEach(function () {
        removeChart(chart);
    });

    it('getData_with_dataType_on_not_linked_data_should_not_throw', function () {
        chart.setOption({
            xAxis: {},
            yAxis: {},
            series: [{
                type: 'line',
                data: [[1, 2], [3, 4], [5, 6]]
            }]
        });

        const seriesModel = chart.getModel().getSeriesByIndex(0) as SeriesModel;
        // A plain (not linked) series data has no `getLinkedData` supplement
        // method. Asking for a linked dataType should degrade gracefully.
        expect(() => seriesModel.getData('node')).not.toThrow();
        expect(seriesModel.getData('node')).toBe(seriesModel.getData());

        expect(() => seriesModel.getAllData()).not.toThrow();
        expect(seriesModel.getAllData().length).toEqual(1);
        expect(seriesModel.getAllData()[0].data).toBe(seriesModel.getData());
    });

    it('getData_with_dataType_on_linked_data_keeps_working', function () {
        chart.setOption({
            series: [{
                type: 'graph',
                data: [{ name: 'n0' }, { name: 'n1' }],
                links: [{ source: 'n0', target: 'n1' }]
            }]
        });

        const seriesModel = chart.getModel().getSeriesByIndex(0) as SeriesModel;
        const nodeData = seriesModel.getData();
        expect(nodeData.count()).toEqual(2);
        expect(seriesModel.getData('edge').count()).toEqual(1);
        // `null` dataType still returns the main data.
        expect(seriesModel.getData()).toBe(nodeData);

        const allData = seriesModel.getAllData();
        expect(allData.length).toEqual(2);
    });

});

