const task = getCurrentTask(this);
if (task) {
    const data = task.context.data;
    // `getLinkedData` is a supplement method, which only exists on data
    // that has been linked (see `linkSeriesData`). If the data is not
    // linked (or the requested dataType is absent), fall back to the
    // main data rather than throwing. See #19901.
    return (dataType == null || !(data && data.getLinkedData)
        ? data
        : data.getLinkedData(dataType)
    ) as SeriesData<this>;
}

