function getLinkedData(this: SeriesData, dataType?: SeriesDataType): SeriesData {
    const mainData = inner(this).mainData;
    return (dataType == null || mainData == null)
        ? mainData
        : inner(mainData).datas[dataType];
}

/**
 * Get list of all linked data
 */
function getLinkedDataAll(this: SeriesData): {
    data: SeriesData,
    type?: SeriesDataType
}[] {
    const mainData = inner(this).mainData;
    return (mainData == null)
        ? [{ data: mainData }]
        : map(keys(inner(mainData).datas), function (type) {
            return {
                type,
                data: inner(mainData).datas[type]
            };
        });
}

input.new_string:
function getLinkedData(this: SeriesData, dataType?: SeriesDataType): SeriesData {
    const mainData = inner(this).mainData;
    if (dataType == null || mainData == null) {
        return mainData;
    }
    // `datas` may be absent if the link has not been (or is no longer)
    // established. Degrade to `undefined` rather than throwing.
    const datas = inner(mainData).datas;
    return datas && datas[dataType];
}

/**
 * Get list of all linked data
 */
function getLinkedDataAll(this: SeriesData): {
    data: SeriesData,
    type?: SeriesDataType
}[] {
    const mainData = inner(this).mainData;
    const datas = mainData != null && inner(mainData).datas;
    return !datas
        ? [{ data: mainData }]
        : map(keys(datas), function (type) {
            return {
                type,
                data: datas[type]
            };
        });
}

