/**
 * Large data down sampling using min-max.
 *
 * Unlike `downSample`, which only outputs one point for each frame, both
 * the local minimum and the local maximum of every frame are kept here (in
 * data order), so that all the peaks and the troughs of the original data
 * are preserved. NaN (i.e. empty value) is not comparable, but the first
 * one of each frame is kept so that the gaps are not lost.
 *
 * @param valueDimension
 * @param rate
 */
minmaxDownSample(
    valueDimension: DimensionLoose,
    rate: number
): SeriesData<HostModel> {
    const list = cloneListForMapAndSample(this);
    const store = this._store;
    const dimIdx = this._getStoreDimIndex(valueDimension);
    const len = store.count();
    const frameSize = Math.max(Math.floor(1 / rate), 1);
    // Mark the data indices that should be kept. They are collected in
    // ascending order, so the sampled result keeps the original data order.
    const isTurningPoint: boolean[] = [];

    for (let i = 0; i < len; i += frameSize) {
        const frameEnd = Math.min(i + frameSize, len);
        let minIndex = -1;
        let maxIndex = -1;
        let minValue = Infinity;
        let maxValue = -Infinity;
        let firstNaNIndex = -1;

        for (let k = i; k < frameEnd; k++) {
            const value = store.get(dimIdx, k) as number;
            if (isNaN(value)) {
                if (firstNaNIndex < 0) {
                    firstNaNIndex = k;
                }
                continue;
            }
            // Compare the actual value rather than its absolute value.
            // Otherwise the local minimum is lost when the whole frame is
            // on the same side of zero.
            if (value < minValue) {
                minValue = value;
                minIndex = k;
            }
            if (value > maxValue) {
                maxValue = value;
                maxIndex = k;
            }
        }

        if (firstNaNIndex >= 0) {
            isTurningPoint[firstNaNIndex] = true;
        }
        if (minIndex >= 0) {
            isTurningPoint[minIndex] = true;
        }
        if (maxIndex >= 0) {
            isTurningPoint[maxIndex] = true;
        }
    }

    list._store = store.filter([], function (dataIndex: number) {
        return !!isTurningPoint[dataIndex];
    });

    return list as SeriesData<HostModel>;
}

