function createData(values: number[]): SeriesData {
    const data = new SeriesData(['x', 'y'], new Model());
    data.initData(values.map((val, idx) => [idx, val]));
    return data;
}

function readDim(data: SeriesData, dim: string): number[] {
    const result: number[] = [];
    for (let i = 0; i < data.count(); i++) {
        result.push(data.get(dim, i) as number);
    }
    return result;
}

describe('data/minmaxDownSample', function () {

    it('keeps_local_min_and_max_in_data_order', function () {
        //                    frame 0        frame 1        frame 2
        const source = [1, 5, 3, 2, /**/ 9, 4, 7, 6, /**/ 0, -3, 8, 2];
        const data = createData(source);
        // frameSize === 4
        const sampled = data.minmaxDownSample('y', 1 / 4);

        // frame 0: min 1 (idx 0), max 5 (idx 1) -> [1, 5]
        // frame 1: max 9 (idx 4), min 4 (idx 5) -> [9, 4]
        // frame 2: min -3 (idx 9), max 8 (idx 10) -> [-3, 8]
        expect(readDim(sampled, 'y')).toEqual([1, 5, 9, 4, -3, 8]);
        // Must stay in data order (the base dim is monotonic here).
        expect(readDim(sampled, 'x')).toEqual([0, 1, 4, 5, 9, 10]);
    });

    it('keeps_trough_when_the_frame_does_not_cross_zero', function () {
        // All the values are far away from zero. The old implementation
        // compared `Math.abs(value)`, so the local minimum of each frame was
        // never picked up and the troughs disappeared.
        const source = [50, 70, 30, 50, /**/ 50, 30, 70, 50];
        const data = createData(source);
        const sampled = data.minmaxDownSample('y', 1 / 4);

        expect(readDim(sampled, 'y')).toEqual([70, 30, 30, 70]);
        expect(readDim(sampled, 'x')).toEqual([1, 2, 5, 6]);
    });

    it('keeps_trough_when_all_values_are_negative', function () {
        const source = [-50, -70, -30, -50, /**/ -50, -30, -70, -50];
        const data = createData(source);
        const sampled = data.minmaxDownSample('y', 1 / 4);

        // In data order: -70 (idx 1) then -30 (idx 2); -30 (idx 5) then -70 (idx 6).
        expect(readDim(sampled, 'y')).toEqual([-70, -30, -30, -70]);
        expect(readDim(sampled, 'x')).toEqual([1, 2, 5, 6]);
    });

    it('single_point_frame_and_flat_frame', function () {
        const source = [7, 7, 7, 7, /**/ 1, 2];
        const data = createData(source);
        const sampled = data.minmaxDownSample('y', 1 / 4);

        // Frame 0 is flat: min and max are the same point, output it once.
        expect(readDim(sampled, 'y')).toEqual([7, 1, 2]);
        expect(readDim(sampled, 'x')).toEqual([0, 4, 5]);
    });

    it('keeps_the_gap_of_empty_values', function () {
        const data = new SeriesData(['x', 'y'], new Model());
        data.initData([
            [0, 1], [1, 5], [2, null], [3, 2],
            [4, 9], [5, 4], [6, 7], [7, 6]
        ]);
        const sampled = data.minmaxDownSample('y', 1 / 4);

        const values = readDim(sampled, 'y');
        // The empty value is kept (so that the gap is not lost) and the
        // extrema of the frame are still there.
        expect(values.length).toEqual(5);
        expect(isNaN(values[0])).toEqual(true);
        expect(values.slice(1)).toEqual([1, 5, 9, 4]);
        expect(readDim(sampled, 'x')).toEqual([2, 0, 1, 4, 5]);
    });

    it('does_not_modify_the_source_data', function () {
        const source = [1, 5, 3, 2, 9, 4, 7, 6];
        const data = createData(source);
        data.minmaxDownSample('y', 1 / 4);
        expect(data.count()).toEqual(8);
        expect(readDim(data, 'y')).toEqual(source);
    });

});

