    it('does_not_modify_the_source_data', function () {
        const source = [1, 5, 3, 2, 9, 4, 7, 6];
        const data = createData(source);
        data.minmaxDownSample('y', 1 / 4);
        expect(data.count()).toEqual(8);
        expect(readDim(data, 'y')).toEqual(source);
    });

    it('line_with_minmax_sampling_keeps_peaks_and_troughs', function () {
        const chart = createChart({ width: 500, height: 400 });

        const values: number[][] = [];
        let rawMin = Infinity;
        let rawMax = -Infinity;
        for (let i = 0; i < 2000; i++) {
            // All values are positive and far away from zero, which is the
            // case that the previous magnitude-based implementation broke.
            const val = 50 + 20 * Math.sin(i / 3);
            values.push([i, val]);
            rawMin = Math.min(rawMin, val);
            rawMax = Math.max(rawMax, val);
        }

        chart.setOption({
            xAxis: { type: 'value' },
            yAxis: { type: 'value' },
            series: [{
                type: 'line',
                sampling: 'minmax',
                showSymbol: false,
                data: values
            }]
        });

        const seriesModel = chart.getModel().getSeriesByIndex(0) as SeriesModel;
        const sampled = seriesModel.getData();
        // Down sampling really happened.
        expect(sampled.count()).toBeLessThan(2000);
        expect(sampled.count()).toBeGreaterThan(0);

        // Both the peaks and the troughs of the source data survived.
        const extent = sampled.getDataExtent(sampled.mapDimension('y'));
        expect(extent[0]).toBeCloseTo(rawMin, 8);
        expect(extent[1]).toBeCloseTo(rawMax, 8);

        removeChart(chart);
    });

});

